function parseAddr(w) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(w)
  if (!m) return null
  const r = parseInt(m[2], 10)
  if (r < 1) return null
  return { c: colIdx(m[1].toUpperCase()), r }
}
const key = (a) => a.c * 1000 + a.r
const keyName = (k) => colName(Math.floor(k / 1000)) + (k % 1000)

// ---- parse sheet
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const cells = new Map()
lines.forEach((raw, i) => {
  const s = raw.replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') return
  let j = 0
  while (j < s.length && s[j] !== ' ' && s[j] !== '\t') j++
  const tok = s.slice(0, j)
  while (j < s.length && (s[j] === ' ' || s[j] === '\t')) j++
  const content = s.slice(j)
  const a = parseAddr(tok)
  if (!a) fail(`error: line ${i + 1}: invalid cell address ${tok}`)
  const k = key(a)
  if (cells.has(k)) fail(`error: line ${i + 1}: cell ${keyName(k)} is declared twice`)
  cells.set(k, { content })
})
function fail(m) { process.stderr.write(m + '\n'); process.exit(2) }

// ---- formula parser
function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) { toks.push({ k: 'num', v: parseFloat(m[0]) }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) { toks.push({ k: 'word', v: m[0] }); i += m[0].length; continue }
    if ((m = /^(<>|<=|>=|[-+*\/^=<>(),:])/.exec(s.slice(i)))) { toks.push({ k: 'op', v: m[0] }); i += m[0].length; continue }
    return null
  }
  return toks
}

// returns {ast, misplaced} or null
function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  let misplaced = false
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  const BAD = {}
  function expr() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'cmp', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { t: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { t: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { t: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    if (p >= toks.length) throw BAD
    const t = toks[p++]
    if (t.k === 'num') return { t: 'num', v: t.v }
    if (t.k === 'op') {
      if (t.v === '(') {
        const e = expr()
        if (!isOp(')')) throw BAD
        p++
        return { t: 'paren', e }
      }
      throw BAD
    }
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) p++
      else {
        for (;;) {
          args.push(arg())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          throw BAD
        }
      }
      return { t: 'call', name: t.v.toUpperCase(), args }
    }
    const up = t.v.toUpperCase()
    if (up === 'TRUE') return { t: 'bool', v: true }
    if (up === 'FALSE') return { t: 'bool', v: false }
    if (isOp(':')) {
      p++
      if (p >= toks.length || toks[p].k !== 'word') throw BAD
      const w2 = toks[p++].v
      return { t: 'range', a: t.v, b: w2 }
    }
    return { t: 'ref', w: t.v }
  }
  function arg() {
    const e = expr()
    return e
  }
  // mark misplaced ranges
  function walk(n, direct) {
    switch (n.t) {
      case 'range': if (!direct) misplaced = true; break
      case 'paren': walk(n.e, false); break
      case 'un': walk(n.e, false); break
      case 'bin': case 'cmp': walk(n.l, false); walk(n.r, false); break
      case 'call': n.args.forEach((a) => walk(a, true)); break
    }
  }
  try {
    const ast = expr()
    if (p !== toks.length) return null
    walk(ast, false)
    return { ast, misplaced }
  } catch (e) {
    if (e === BAD) return null
    throw e
  }
}

function rangeKeys(n) {
  const a = parseAddr(n.a), b = parseAddr(n.b)
  if (!a || !b) return null
  const out = []
  for (let c = Math.min(a.c, b.c); c <= Math.max(a.c, b.c); c++)
    for (let r = Math.min(a.r, b.r); r <= Math.max(a.r, b.r); r++) out.push(c * 1000 + r)
  return out
}

function parseCell(cell) {
  if (cell.parsed !== undefined) return cell.parsed
  cell.parsed = cell.content[0] === '=' ? parseFormula(cell.content.slice(1)) : null
  return cell.parsed
}

// ---- evaluation
const memo = new Map()
const active = new Set()
function cellValue(k) {
  if (memo.has(k)) return memo.get(k)
  const cell = cells.get(k)
  if (!cell) return ZERO
  if (active.has(k)) return err('#CYCLE!')
  active.add(k)
  let v
  const c = cell.content
  if (c[0] === '=') {
    const f = parseCell(cell)
    if (!f || f.misplaced) v = err('#ERR!')
    else v = evalNode(f.ast)
  } else if (c === '') v = ZERO
  else if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) v = num(parseFloat(c))
  else if (ERRS.includes(c)) v = err(c)
  else v = { t: 's', v: c }
  active.delete(k)
  memo.set(k, v)
  return v
}

function toNum(v) {
  if (v.t === 'n') return v
  if (v.t === 'b') return num(v.v ? 1 : 0)
  if (v.t === 's') return err('#VALUE!')
  return v
}
const fin = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))
const rank = { n: 0, s: 1, b: 2 }
function cpCmp(a, b) {
  const x = Array.from(a), y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
function cmpVals(a, b) {
  if (a.t !== b.t) return rank[a.t] - rank[b.t]
  if (a.t === 'n') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.t === 's') return cpCmp(a.v, b.v)
  return (a.v ? 1 : 0) - (b.v ? 1 : 0)
}

function evalNode(n) {
  switch (n.t) {
    case 'num': return num(n.v)
    case 'bool': return { t: 'b', v: n.v }
    case 'paren': return evalNode(n.e)
    case 'range': return err('#ERR!')
    case 'ref': {
      const a = parseAddr(n.w)
      return a ? cellValue(key(a)) : err('#REF!')
    }
    case 'un': {
      const x = toNum(evalNode(n.e))
      if (x.t === 'e') return x
      return num(n.op === '-' ? -x.v : x.v)
    }
    case 'bin': {
      const l = toNum(evalNode(n.l))
      if (l.t === 'e') return l
      const r = toNum(evalNode(n.r))
      if (r.t === 'e') return r
      switch (n.op) {
        case '+': return fin(l.v + r.v)
        case '-': return fin(l.v - r.v)
        case '*': return fin(l.v * r.v)
        case '/': return r.v === 0 ? err('#DIV/0!') : fin(l.v / r.v)
        default: return fin(Math.pow(l.v, r.v))
      }
    }
    case 'cmp': {
      const l = evalNode(n.l)
      if (l.t === 'e') return l
      const r = evalNode(n.r)
      if (r.t === 'e') return r
      const d = cmpVals(l, r)
      const res = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
      return { t: 'b', v: res }
    }
    case 'call': return evalCall(n)
  }
}

function evalCall(n) {
  const name = n.name
  const AGG = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
  if (!AGG.includes(name) && name !== 'ABS' && name !== 'IF') return err('#NAME?')
  const argc = n.args.length
  if ((AGG.includes(name) && argc < 1) || (name === 'ABS' && argc !== 1) || (name === 'IF' && argc !== 3)) return err('#ERR!')
  if (name === 'IF') {
    if (n.args.some((a) => a.t === 'range')) return err('#ERR!')
    const c = evalNode(n.args[0])
    if (c.t === 'e') return c
    let truth
    if (c.t === 'b') truth = c.v
    else if (c.t === 'n') truth = c.v !== 0
    else return err('#VALUE!')
    return evalNode(n.args[truth ? 1 : 2])
  }
  if (name === 'ABS') {
    if (n.args[0].t === 'range') return err('#ERR!')
    const x = toNum(evalNode(n.args[0]))
    return x.t === 'e' ? x : num(Math.abs(x.v))
  }
  const vals = []
  for (const a of n.args) {
    if (a.t === 'range') {
      const ks = rangeKeys(a)
      if (!ks) vals.push(err('#REF!'))
      else for (const k of ks) vals.push(cellValue(k))
    } else vals.push(evalNode(a))
  }
  const e = vals.find((v) => v.t === 'e')
  if (e) return e
  if (name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.t === 'e') return x
    nums.push(x.v)
  }
  switch (name) {
    case 'SUM': return fin(nums.reduce((s, x) => s + x, 0))
    case 'AVG': return fin(nums.reduce((s, x) => s + x, 0) / nums.length)
    case 'MIN': return num(nums.reduce((s, x) => (x < s ? x : s), nums[0]))
    default: return num(nums.reduce((s, x) => (x > s ? x : s), nums[0]))
  }
}

function fmt(v) {
  if (v.t === 'n') return String(Number(v.v.toPrecision(10)))
  if (v.t === 'b') return v.v ? 'TRUE' : 'FALSE'
  return v.v
}

function names(ast, set) {
  switch (ast.t) {
    case 'ref': { const a = parseAddr(ast.w); if (a) set.add(key(a)); break }
    case 'range': { const ks = rangeKeys(ast); if (ks) ks.forEach((k) => set.add(k)); break }
    case 'paren': case 'un': names(ast.e, set); break
    case 'bin': case 'cmp': names(ast.l, set); names(ast.r, set); break
    case 'call': ast.args.forEach((a) => names(a, set)); break
  }
}

const keys = [...cells.keys()].sort((a, b) => a - b)
const out = []
for (const k of keys) {
  if (mode === 'values') out.push(`${keyName(k)}=${fmt(cellValue(k))}`)
  else {
    const set = new Set()
    const cell = cells.get(k)
    if (cell.content[0] === '=') {
      const f = parseCell(cell)
      if (f) names(f.ast, set)
    }
    out.push(`${keyName(k)}:` + [...set].sort((a, b) => a - b).map((x) => ' ' + keyName(x)).join(''))
